const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
    let browser;
    try {
        browser = await chromium.launch();
    } catch (e) {
        console.error('Chromium launch failed, attempting to install...');
        const { execSync } = require('child_process');
        execSync('npx playwright install chromium >/dev/null 2>&1');
        browser = await chromium.launch();
    }

    const page = await browser.newPage();
    const htmlPath = path.join(process.cwd(), 'index.html');
    const htmlContent = fs.readFileSync(htmlPath, 'utf8');

    // Using file:// URL might be better for external resources if they were local, 
    // but here we just set content.
    await page.setContent(htmlContent, { waitUntil: 'load' });

    // Inject axe
    await page.addScriptTag({ path: '/tmp/axe.min.js' });

    // Run axe
    const results = await page.evaluate(async () => {
        return await window.axe.run();
    });

    await browser.close();

    const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
    const bp = results.violations.filter(v => v.tags.includes('best-practice'));

    console.log(JSON.stringify({
        wcag: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
        bp: bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
    }, null, 2));

    if (wcag.length > 0) {
        process.exit(1);
    }
})();

