        <nav aria-label="Primary">
            <div class="logo">PhotoLibrary</div>
        </nav>
    </header>

    <main id="main-content" tabindex="-1">
        <section class="image-preview-container">
            <div class="image-card">
                <div class="image-wrapper">
                    <img src="https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&q=80&w=1000" alt="Landscape with mountains and a lake at sunset">
                </div>
                <div class="image-details">
                    <h1>Mountain Sunset</h1>
                    <p>Added on May 6, 2026</p>
                    <button type="button" class="trigger btn btn-danger" id="open-delete-dialog">Delete Image</button>
                </div>
            </div>
        </section>
    </main>

    <dialog id="delete-dialog" role="alertdialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
        <div class="dialog-content">
            <h2 id="dialog-title">Delete this image?</h2>
            <p id="dialog-description">Are you sure you want to delete "Mountain Sunset"? This action cannot be undone and the image will be permanently removed from your library.</p>
