                <button type="button" class="btn btn-secondary" id="cancel-delete">Cancel</button>
                <button type="button" class="btn btn-danger" id="confirm-delete">Delete</button>
            </div>
        </div>
    </dialog>

    <footer>
        <p>&copy; 2026 PhotoLibrary Inc.</p>
    </footer>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const dialog = document.getElementById('delete-dialog');
            const trigger = document.getElementById('open-delete-dialog');
            const cancelButton = document.getElementById('cancel-delete');
            const confirmButton = document.getElementById('confirm-delete');

            // Open dialog
            trigger.addEventListener('click', () => {
                dialog.showModal();
            });

            // Close dialog on cancel
            cancelButton.addEventListener('click', () => {
                dialog.close('cancel');
            });

            // Confirm delete
            confirmButton.addEventListener('click', () => {
                console.log('Image deleted');
                dialog.close('delete');
                // In a real app, you might remove the image from the DOM or redirect
                alert('Image has been deleted from your library.');
            });

            // Close on backdrop click (optional but common)
            dialog.addEventListener('click', (event) => {
                if (event.target === dialog) {
                    dialog.close('cancel');
                }
            });

            // Accessibility: prevent accidental double clicks if button is slow
            confirmButton.addEventListener('click', () => {
                confirmButton.disabled = true;
                setTimeout(() => {
                    confirmButton.disabled = false;
                }, 1000);
            });
        });
    </script>
</body>
