            background: var(--card-bg);
            border-radius: var(--radius);
            box-shadow: var(--shadow);
            overflow: hidden;
            max-width: 600px;
            width: 100%;
        }

        .image-wrapper img {
            width: 100%;
            height: auto;
            display: block;
            aspect-ratio: 16 / 9;
            object-fit: cover;
        }

        .image-details {
            padding: 1.5rem;
            text-align: center;
        }

        .image-details h1 {
            margin: 0 0 0.5rem;
            font-size: 1.5rem;
        }

        .image-details p {
            color: var(--text-muted);
            margin: 0 0 1.5rem;
        }

        .btn {
            appearance: none;
            border: none;
            border-radius: 8px;
            cursor: pointer;
            font-size: 0.875rem;
            font-weight: 600;
            padding: 0.625rem 1.25rem;
            transition: background-color 0.2s, transform 0.1s;
        }

        .btn:active {
            transform: scale(0.98);
        }

        .btn:focus-visible {
            outline: none;
            box-shadow: var(--focus-ring);
        }

        .btn-danger {
            background-color: var(--danger-color);
            color: white;
        }

        .btn-danger:hover {
            background-color: var(--danger-hover);
        }

        .btn-secondary {
            background-color: var(--secondary-color);
            color: white;
        }

        .btn-secondary:hover {
            background-color: var(--secondary-hover);
        }

        /* Dialog Styling */
        dialog {
            border: none;
            border-radius: var(--radius);
            padding: 0;
            box-shadow: 0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1);
            max-width: 400px;
            width: 90%;
        }

        dialog::backdrop {
            background: rgba(15, 23, 42, 0.5);
            backdrop-filter: blur(4px);
        }

        .dialog-content {
            padding: 1.5rem;
        }

        .dialog-content h2 {
            margin: 0 0 1rem;
            font-size: 1.25rem;
        }

        .dialog-content p {
            color: var(--text-muted);
            margin: 0 0 1.5rem;
        }

        .dialog-actions {
            display: flex;
            justify-content: flex-end;
            gap: 0.75rem;
        }

        footer {
            padding: 2rem;
            text-align: center;
            color: var(--text-muted);
            font-size: 0.875rem;
        }

        @media (max-width: 480px) {
            .dialog-actions {
                flex-direction: column;
            }

            .dialog-actions .btn {
                width: 100%;
            }
        }
    </style>
</head>
<body>
    <a href="#main-content" class="skip-link">Skip to main content</a>

    <header>
        <nav aria-label="Primary">
            <div class="logo">PhotoLibrary</div>
        </nav>
    </header>

    <main id="main-content" tabindex="-1">
        <section class="image-preview-container">
            <div class="image-card">
                <div class="image-wrapper">
                    <img src="https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&q=80&w=1000" alt="Landscape with mountains and a lake at sunset">
                </div>
                <div class="image-details">
                    <h1>Mountain Sunset</h1>
                    <p>Added on May 6, 2026</p>
                    <button type="button" class="trigger btn btn-danger" id="open-delete-dialog">Delete Image</button>
                </div>
            </div>
        </section>
    </main>

    <dialog id="delete-dialog" role="alertdialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
        <div class="dialog-content">
            <h2 id="dialog-title">Delete this image?</h2>
            <p id="dialog-description">Are you sure you want to delete "Mountain Sunset"? This action cannot be undone and the image will be permanently removed from your library.</p>
            <div class="dialog-actions">
                <button type="button" class="btn btn-secondary" id="cancel-delete">Cancel</button>
                <button type="button" class="btn btn-danger" id="confirm-delete">Delete</button>
            </div>
        </div>
    </dialog>

    <footer>
        <p>&copy; 2026 PhotoLibrary Inc.</p>
    </footer>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const dialog = document.getElementById('delete-dialog');
            const trigger = document.getElementById('open-delete-dialog');
            const cancelButton = document.getElementById('cancel-delete');
            const confirmButton = document.getElementById('confirm-delete');

            // Open dialog
            trigger.addEventListener('click', () => {
                dialog.showModal();
            });

            // Close dialog on cancel
            cancelButton.addEventListener('click', () => {
                dialog.close('cancel');
            });

            // Confirm delete
            confirmButton.addEventListener('click', () => {
                console.log('Image deleted');
                dialog.close('delete');
                // In a real app, you might remove the image from the DOM or redirect
                alert('Image has been deleted from your library.');
            });

            // Close on backdrop click (optional but common)
            dialog.addEventListener('click', (event) => {
                if (event.target === dialog) {
                    dialog.close('cancel');
                }
            });

            // Accessibility: prevent accidental double clicks if button is slow
            confirmButton.addEventListener('click', () => {
                confirmButton.disabled = true;
                setTimeout(() => {
                    confirmButton.disabled = false;
                }, 1000);
            });
        });
    </script>
</body>
</html>
